r"""The ``boardwright`` command.

Boardwright normally runs as a Claude Code plugin: the plugin starts the
server and the server prepares the PC by itself (folders, Altium scripts).
These commands are for checking and repairing by hand.

    boardwright [serve]     start the MCP server on stdio (what the plugin runs)
    boardwright setup       prepare this PC now (--copilot also registers the
                            plugin for GitHub Copilot in VS Code, --clean-old
                            removes older eda-agent / Boardwright set-ups)
    boardwright doctor      check the install and the live Altium link
    boardwright relaunch    start the bridge script in the running Altium
    boardwright remove      remove what setup or Boardwright 1.0 registered
                            (add --data to delete the data folder)
    boardwright info        print versions and folders as JSON
    boardwright engine ...  run an engine subcommand directly (advanced)
"""
from __future__ import annotations

import argparse
import json
import os
import shutil
import subprocess
from pathlib import Path
from typing import Optional

from . import __version__, engine, paths, prepare

SERVER_KEY = "boardwright"
PLUGIN_NAME = "boardwright"
# Skill links that Boardwright 1.0's setup made in ~/.claude/skills. The
# plugin brings its own skill, so these would show it twice.
OLD_SKILL_LINKS = ("boardwright-schematic", "boardwright-layout",
                   # the altium-agent-plugin skills Boardwright grew from
                   "altium-schematic", "altium-pcb-layout")
# Names an earlier, separately registered eda-agent server may use. Two
# servers on one Altium share the bridge and confuse each other.
LEGACY_SERVER_KEYS = ("altium", "eda-agent", "eda-agent-altium")
LEGACY_PLUGINS = ("altium-schematic",)
# VS Code settings that make GitHub Copilot load the plugin folder.
COPILOT_LOCATIONS = "chat.pluginLocations"
COPILOT_ENABLED = "chat.plugins.enabled"
KEY_ENV_VARS = ("MOUSER_API_KEY", "DIGIKEY_CLIENT_ID", "DIGIKEY_CLIENT_SECRET",
                "NEXAR_ACCESS_TOKEN")


# --------------------------------------------------------------------------
# helpers
# --------------------------------------------------------------------------

def _ok(msg: str) -> None:
    print(f"  [ok]   {msg}")


def _warn(msg: str) -> None:
    print(f"  [!]    {msg}")


def _fail(msg: str) -> None:
    print(f"  [FAIL] {msg}")


def _claude_dir() -> Path:
    """Claude Code's config folder (CLAUDE_CONFIG_DIR moves it)."""
    override = os.environ.get("CLAUDE_CONFIG_DIR")
    return Path(override) if override else Path.home() / ".claude"


def _claude_skills_dir() -> Path:
    return _claude_dir() / "skills"


def _vscode_user_dir() -> Path:
    appdata = os.environ.get("APPDATA") or str(Path.home() / "AppData" / "Roaming")
    return Path(appdata) / "Code" / "User"


def _vscode_mcp_json() -> Path:
    return _vscode_user_dir() / "mcp.json"


def _vscode_settings_json() -> Path:
    return _vscode_user_dir() / "settings.json"


def _claude_exe() -> Optional[str]:
    """The Claude Code CLI: on PATH, or the copy inside the VS Code extension."""
    exe = os.environ.get("BOARDWRIGHT_CLAUDE") or shutil.which("claude")
    if exe:
        return exe
    def version(p: Path) -> tuple:
        tail = p.name.rsplit("-", 2)[-2] if p.name.count("-") >= 2 else ""
        return tuple(int(x) for x in tail.split(".") if x.isdigit())
    ext_root = Path.home() / ".vscode" / "extensions"
    for ext in sorted(ext_root.glob("anthropic.claude-code-*"), key=version, reverse=True):
        exe_path = ext / "resources" / "native-binary" / "claude.exe"
        if exe_path.is_file():
            return str(exe_path)
    return None


def _active_install() -> Optional[Path]:
    """The folder Claude Code runs the installed plugin from (one per
    version, under plugins/cache), as installed_plugins.json records it."""
    record = _read_json(_claude_dir() / "plugins" / "installed_plugins.json") or {}
    for entry in (record.get("plugins") or {}).get(f"{PLUGIN_NAME}@{PLUGIN_NAME}", []):
        folder = Path(entry.get("installPath") or "")
        if entry.get("scope", "user") == "user" and _is_boardwright_plugin(folder):
            return folder
    return None


def _plugin_folder() -> Optional[Path]:
    """The plugin folder Copilot should load: the version Claude Code has
    installed, else the folder this runtime runs from.

    Not the marketplace copy: VS Code watches the folder it loads, and a
    watched folder cannot be renamed, so `/plugin marketplace update`
    failed with EPERM while VS Code was open (measured 2026-11-08). A
    version folder is never renamed; an update makes a new one, and the
    server moves Copilot to it (retarget_copilot)."""
    return _active_install() or paths.install_root()


def retarget_copilot() -> Optional[str]:
    """Move Copilot's Boardwright entry to the active install, when the
    user has one and it names another folder. Runs at every server start;
    quiet, never raises. Returns the new folder when it changed something."""
    try:
        active, here = _active_install(), paths.install_root()
        if active is None or here is None or os.path.normcase(str(active)) != os.path.normcase(str(here)):
            return None   # only the active version's server moves the entry
        settings_path = _vscode_settings_json()
        settings = _read_json(settings_path)
        if not settings:
            return None
        locations = settings.get(COPILOT_LOCATIONS) or {}
        mine = [k for k, on in locations.items() if on and _is_boardwright_plugin(Path(k))]
        key = active.as_posix()
        if not mine or mine == [key]:
            return None
        for k in mine:
            del locations[k]
        locations[key] = True
        _write_json(settings_path, settings)
        return key
    except Exception:
        return None


def _write_json(path: Path, data: dict) -> None:
    """Write JSON after keeping the previous file as <name>.bak."""
    if path.exists():
        shutil.copy2(path, path.with_name(path.name + ".bak"))
    path.write_text(json.dumps(data, indent=4) + "\n", encoding="utf-8")


def _copilot_registered() -> Optional[str]:
    """The Boardwright folder Copilot loads, if VS Code registers one."""
    settings = _read_json(_vscode_settings_json()) or {}
    for folder, on in (settings.get(COPILOT_LOCATIONS) or {}).items():
        if on and _is_boardwright_plugin(Path(folder)):
            return folder
    return None


def _is_boardwright_plugin(folder: Path) -> bool:
    manifest = _read_json(folder / ".claude-plugin" / "plugin.json")
    return bool(manifest) and manifest.get("name") == PLUGIN_NAME


def _claude_json() -> Path:
    override = os.environ.get("CLAUDE_CONFIG_DIR")
    return Path(override) / ".claude.json" if override else Path.home() / ".claude.json"


def _read_json(path: Path) -> Optional[dict]:
    try:
        return json.loads(path.read_text(encoding="utf-8-sig"))
    except FileNotFoundError:
        return {}
    except (OSError, ValueError):
        return None


def _is_link(p: Path) -> bool:
    return p.is_symlink() or (hasattr(os.path, "isjunction") and os.path.isjunction(p))


def _enabled_plugins() -> set[str]:
    """Plugin names (without @marketplace) enabled in Claude Code."""
    settings = _read_json(_claude_dir() / "settings.json") or {}
    return {key.split("@", 1)[0]
            for key, on in (settings.get("enabledPlugins") or {}).items() if on}


def _registered_servers() -> dict[str, set[str]]:
    """Server keys registered outside any plugin, per client."""
    claude = _read_json(_claude_json()) or {}
    vscode = _read_json(_vscode_mcp_json()) or {}
    return {"Claude Code": set((claude.get("mcpServers") or {}).keys()),
            "VS Code": set((vscode.get("servers") or {}).keys())}


# --------------------------------------------------------------------------
# setup (the server does the same by itself; this is the verbose version)
# --------------------------------------------------------------------------

def _setup_copilot() -> bool:
    """Make GitHub Copilot in VS Code load the Boardwright plugin folder.

    Copilot reads Claude-format plugins (skills and .mcp.json, with
    ${CLAUDE_PLUGIN_ROOT} filled in), so it loads the same folder Claude
    Code installed; the server shows it the short tool list.
    """
    folder = _plugin_folder()
    if folder is None:
        _warn("Copilot: no installed Boardwright plugin folder found; install the "
              "plugin in Claude Code first")
        return False
    settings_path = _vscode_settings_json()
    if not settings_path.parent.is_dir():
        _warn("Copilot: VS Code user folder not found; skipped")
        return False
    settings = _read_json(settings_path)
    key = folder.as_posix()
    if settings is None:
        _warn(f"Copilot: {settings_path} has comments, so it is left as it is. "
              "Add this to it by hand (Ctrl+Shift+P > Preferences: Open User Settings (JSON)):")
        print(json.dumps({COPILOT_LOCATIONS: {key: True}, COPILOT_ENABLED: True}, indent=4))
        return False
    locations = settings.get(COPILOT_LOCATIONS) or {}
    # Drop other Boardwright folders (an older cache path), keep the rest.
    locations = {k: v for k, v in locations.items()
                 if k == key or not _is_boardwright_plugin(Path(k))}
    locations[key] = True
    settings[COPILOT_LOCATIONS] = locations
    settings.setdefault(COPILOT_ENABLED, True)
    _write_json(settings_path, settings)
    _ok(f"Copilot: loads the plugin from {folder} (VS Code settings, backup .bak)")
    # Boardwright 1.1.0rc2's --copilot registered the server in mcp.json; with
    # the plugin loaded as well, Copilot would start it twice.
    mcp_cfg = _read_json(_vscode_mcp_json())
    if mcp_cfg and SERVER_KEY in (mcp_cfg.get("servers") or {}):
        del mcp_cfg["servers"][SERVER_KEY]
        _write_json(_vscode_mcp_json(), mcp_cfg)
        _ok("Copilot: the separate 'boardwright' server entry in mcp.json removed")
    return True


def _clean_old() -> int:
    """Remove older set-ups that would fight Boardwright for Altium or show
    a second skill. Every removed entry is saved first. Returns how many."""
    removed: dict = {"claude_code_servers": {}, "vscode_servers": {}, "skill_links": {},
                     "plugins_disabled": []}
    claude_cfg = _read_json(_claude_json()) or {}
    old_claude = {k: v for k, v in (claude_cfg.get("mcpServers") or {}).items()
                  if k in LEGACY_SERVER_KEYS}
    exe = _claude_exe()
    for key, entry in old_claude.items():
        if exe is None:
            _warn(f"Claude Code CLI not found: remove the '{key}' server by hand "
                  f"(claude mcp remove {key} -s user)")
            continue
        r = subprocess.run([exe, "mcp", "remove", key, "-s", "user"],
                           capture_output=True, text=True, stdin=subprocess.DEVNULL)
        if r.returncode == 0:
            removed["claude_code_servers"][key] = entry
            _ok(f"Claude Code: old server '{key}' removed")
    vs_path = _vscode_mcp_json()
    vs_cfg = _read_json(vs_path)
    if vs_cfg:
        servers = vs_cfg.get("servers") or {}
        old_vs = {k: servers[k] for k in LEGACY_SERVER_KEYS if k in servers}
        if old_vs:
            for k in old_vs:
                del servers[k]
            _write_json(vs_path, vs_cfg)
            removed["vscode_servers"] = old_vs
            _ok(f"VS Code: old server(s) {', '.join(old_vs)} removed (backup .bak)")
    for skill in OLD_SKILL_LINKS:
        link = _claude_skills_dir() / skill
        if _is_link(link):
            removed["skill_links"][skill] = os.path.realpath(link)
            os.rmdir(link)  # the link only, never its target
            _ok(f"old skill link {skill} removed (its files stay)")
    for plugin in sorted(set(LEGACY_PLUGINS) & _enabled_plugins()):
        if exe and subprocess.run([exe, "plugin", "disable", plugin], capture_output=True,
                                  text=True, stdin=subprocess.DEVNULL).returncode == 0:
            removed["plugins_disabled"].append(plugin)
            _ok(f"old plugin '{plugin}' disabled")
    count = sum(len(v) for v in removed.values())
    if count:
        note = paths.home() / "old-setup-removed.json"
        note.write_text(json.dumps(removed, indent=2) + "\n", encoding="utf-8")
        _ok(f"what was removed is listed in {note}")
    return count


def cmd_setup(args) -> int:
    print(f"Boardwright {__version__} setup")
    prepare.ensure_folders()
    _ok(f"data folder {paths.home()}")
    prepare.migrate_legacy(_ok)
    scripts_ok = prepare.deploy_scripts(_ok)
    if not scripts_ok:
        _fail("deploying the Altium scripts failed (see above)")
    launcher = prepare.write_launcher()
    if launcher:
        _ok(f"bridge launcher {launcher}")
    if getattr(args, "clean_old", False):
        _clean_old()
    if args.copilot:
        _setup_copilot()
    _report_conflicts()
    print()
    print("Nothing to register in Altium: Boardwright starts its bridge by path.")
    print("Start it in the running Altium with: "
          + (f'"{launcher}"' if launcher else "boardwright relaunch")
          + " (the AI also offers to start it).")
    print("Check everything with: boardwright doctor")
    return 0 if scripts_ok else 1


# --------------------------------------------------------------------------
# remove (undo setup and Boardwright 1.0's registrations; data stays)
# --------------------------------------------------------------------------

def cmd_remove(args) -> int:
    print(f"Boardwright {__version__} remove")
    for skill in OLD_SKILL_LINKS:
        link = _claude_skills_dir() / skill
        if skill.startswith("boardwright") and _is_link(link):
            os.rmdir(link)  # the link only, never its target
            _ok(f"skill link {skill} removed")
    settings = _read_json(_vscode_settings_json())
    locations = (settings or {}).get(COPILOT_LOCATIONS) or {}
    mine = [k for k in locations if _is_boardwright_plugin(Path(k))]
    if mine:
        for k in mine:
            del locations[k]
        _write_json(_vscode_settings_json(), settings)
        _ok("Copilot: Boardwright plugin folder unregistered (VS Code settings, backup .bak)")
    if SERVER_KEY in _registered_servers()["Claude Code"]:
        exe = _claude_exe()
        if exe:
            r = subprocess.run([exe, "mcp", "remove", SERVER_KEY, "-s", "user"],
                               capture_output=True, text=True)
            if r.returncode == 0:
                _ok("Claude Code: separately registered server removed")
        else:
            _warn("Claude Code CLI not found; remove the 'boardwright' entry "
                  f"from {_claude_json()} by hand")
    cfg_path = _vscode_mcp_json()
    cfg = _read_json(cfg_path)
    if cfg and SERVER_KEY in (cfg.get("servers") or {}):
        del cfg["servers"][SERVER_KEY]
        _write_json(cfg_path, cfg)
        _ok("VS Code: server removed (backup .bak)")
    if args.data and any((paths.home() / m).exists() for m in (".git", "pyproject.toml")):
        _fail(f"{paths.home()} holds a source checkout, not only Boardwright data: "
              "not deleted")
    elif args.data:
        shutil.rmtree(paths.home(), ignore_errors=True)
        _ok(f"data folder {paths.home()} deleted")
    else:
        print(f"  Data kept in {paths.home()} (verified parts, fab profiles, runs).")
    print("  The plugin itself: /plugin uninstall boardwright@boardwright in Claude Code.")
    return 0


# --------------------------------------------------------------------------
# doctor
# --------------------------------------------------------------------------

def _report_conflicts() -> int:
    """Warn about anything else that drives Altium or shows the skill twice.
    Returns the number of warnings."""
    warnings = 0
    for client, keys in _registered_servers().items():
        old = sorted(k for k in keys if k in LEGACY_SERVER_KEYS)
        if old:
            _warn(f"{client} also registers {', '.join(old)}: only one server may drive "
                  f"Altium. Fix: boardwright setup --clean-old")
            warnings += 1
    if SERVER_KEY in _registered_servers()["Claude Code"] and PLUGIN_NAME in _enabled_plugins():
        _warn("Claude Code registers 'boardwright' twice (plugin + Boardwright 1.0 "
              "setup): run boardwright remove")
        warnings += 1
    for plugin in sorted(set(LEGACY_PLUGINS) & _enabled_plugins()):
        _warn(f"the old plugin '{plugin}' is enabled. Fix: boardwright setup --clean-old")
        warnings += 1
    links = [s for s in OLD_SKILL_LINKS if _is_link(_claude_skills_dir() / s)]
    if links:
        _warn(f"old skill links {', '.join(links)} in {_claude_skills_dir()} show a "
              "second Altium skill. Fix: boardwright setup --clean-old")
        warnings += 1
    return warnings


def cmd_doctor(args) -> int:
    print(f"Boardwright {__version__} (engine {engine.ENGINE_PACKAGE} {engine.version()})")
    bad = 0
    print("Install")
    if paths.install_root():
        _ok(f"bundled runtime {paths.install_root()}")
    else:
        _warn("development environment (not the bundled runtime)")
    for name, p in paths.data_dirs().items():
        (_ok if p.is_dir() else _fail)(f"{name}: {p}")
        bad += 0 if p.is_dir() else 1
    if prepare.scripts_current():
        _ok(f"Altium scripts of this build in {paths.altium_scripts()}")
    elif paths.script_project().is_file():
        _warn(f"Altium scripts are from {prepare.deployed_build() or 'an older build'}; "
              "they are redeployed when the server next starts (or: boardwright setup)")
    else:
        _fail("Altium scripts missing: start the server once, or run boardwright setup")
        bad += 1
    print("Clients")
    if PLUGIN_NAME in _enabled_plugins():
        _ok("Claude Code: Boardwright plugin enabled")
    else:
        _warn("Claude Code: Boardwright plugin not enabled "
              "(/plugin install boardwright@boardwright)")
    copilot = _copilot_registered()
    if copilot:
        _ok(f"GitHub Copilot: loads the plugin from {copilot}")
    elif SERVER_KEY in _registered_servers()["VS Code"]:
        _warn("GitHub Copilot: only the server is registered (mcp.json), without the "
              "skill. Fix: boardwright setup --copilot")
    else:
        print("  [--]   GitHub Copilot: not set up (optional: boardwright setup --copilot)")
    launcher = prepare.launcher()
    if launcher.is_file():
        _ok(f"bridge launcher {launcher}")
    _report_conflicts()
    print("Part-search keys (optional; web search is used without them)")
    for var in KEY_ENV_VARS:
        print(f"  [{'set' if os.environ.get(var) else '--'}]   {var}")
    if args.offline:
        return 1 if bad else 0
    print("Altium link")
    return 1 if (_live_checks() or bad) else 0


# Engine checks that do not apply to Boardwright (other EDA backends).
_SKIPPED_ENGINE_CHECKS = ("easyeda",)


def _boardwright_fix(text: str) -> str:
    """Engine fix hints name engine commands; say the Boardwright one."""
    for engine_cmd in ("python -m eda_agent.server install-scripts --force",
                       "eda-agent install-scripts --force",
                       "eda-agent install-scripts"):
        text = text.replace(f"`{engine_cmd}`", "`boardwright setup`")
    return text.replace("`eda-agent relaunch`", "`boardwright relaunch`")


def _boardwright_view(check: dict) -> dict:
    """An engine check as it applies to Boardwright.

    The engine asks for the script project in Altium's Global Projects
    list. Boardwright never needs it: it starts the bridge by the project's
    full path (ScriptingSystem:RunScript), and current Altium versions do
    not even show that preferences page."""
    if check.get("name") == "script registration" and check.get("status") != "pass":
        return {**check, "status": "pass", "fix": None,
                "message": "not needed: Boardwright starts the bridge from "
                           f"{paths.script_project()}"}
    return check


def _live_checks() -> int:
    """Run the engine's doctor and report it in Boardwright's format.
    Returns the number of critical failures."""
    import contextlib
    import io

    out = io.StringIO()
    with contextlib.redirect_stdout(out):
        engine.run_engine_cli(["doctor", "--json"])
    try:
        report = json.loads(out.getvalue())
    except ValueError:
        print(out.getvalue())
        _fail("engine doctor gave no readable report")
        return 1
    critical = 0
    for check in report.get("checks", []):
        check = _boardwright_view(check)
        name = check.get("name", "")
        if any(skip in name.lower() for skip in _SKIPPED_ENGINE_CHECKS):
            continue
        status = check.get("status")
        line = name + (f": {check['message']}" if check.get("message") else "")
        if status == "pass":
            _ok(line)
        elif status == "skip":
            print(f"  [--]   {line}")
        elif status == "warn":
            _warn(line)
        else:
            _fail(line)
            if check.get("severity") == "critical":
                critical += 1
        if status in ("warn", "fail") and check.get("fix"):
            print(f"         fix: {_boardwright_fix(check['fix'])}")
    return critical


# --------------------------------------------------------------------------
# entry point
# --------------------------------------------------------------------------

def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        prog="boardwright",
        description="Boardwright - AI design assistant for Altium Designer.")
    p.add_argument("--version", action="version",
                   version=f"boardwright {__version__} (engine {engine.version()})")
    sub = p.add_subparsers(dest="command")
    sub.add_parser("serve", help="start the MCP server on stdio (default)")
    s = sub.add_parser("setup", help="prepare this PC now (the server also does it)")
    s.add_argument("--copilot", action="store_true",
                   help="also make GitHub Copilot in VS Code load the plugin")
    s.add_argument("--clean-old", action="store_true",
                   help="remove older eda-agent / Altium skill set-ups (saved first)")
    d = sub.add_parser("doctor", help="check the install and the Altium link")
    d.add_argument("--offline", action="store_true", help="skip the live Altium check")
    r = sub.add_parser("relaunch", help="start the bridge script in the running Altium")
    r.add_argument("--force", action="store_true", help="even if the bridge answers")
    rm = sub.add_parser("remove", help="remove what setup or Boardwright 1.0 registered")
    rm.add_argument("--data", action="store_true",
                    help="also delete the data folder (verified parts, fab profiles, runs)")
    sub.add_parser("info", help="print versions and folders as JSON")
    e = sub.add_parser("engine", help="run an engine subcommand (advanced)")
    e.add_argument("rest", nargs=argparse.REMAINDER)
    return p


def main(argv: Optional[list[str]] = None) -> int:
    engine.configure()
    args = build_parser().parse_args(argv)
    if args.command in (None, "serve"):
        from . import server
        return server.serve()
    if args.command == "setup":
        return cmd_setup(args)
    if args.command == "doctor":
        return cmd_doctor(args)
    if args.command == "relaunch":
        extra = ["--force"] if args.force else []
        return engine.run_engine_cli(
            ["relaunch", "--prjscr", str(paths.script_project()), *extra])
    if args.command == "remove":
        return cmd_remove(args)
    if args.command == "info":
        from . import server
        print(json.dumps(server.info(), indent=2))
        return 0
    if args.command == "engine":
        return engine.run_engine_cli(args.rest)
    return 2
